const listTemplates = `-- name: ListTemplates :many
SELECT t.id, t.name, t.current_version_id, t.updated_at, v.version, v.subject, v.body, v.ai_generated
FROM outreach.templates t LEFT JOIN outreach.template_versions v ON v.tenant_id = t.tenant_id AND v.id = t.current_version_id
WHERE t.tenant_id = $1 AND t.deleted_at IS NULL ORDER BY t.name
`

type ListTemplatesRow struct {
	ID               uuid.UUID
	Name             string
	CurrentVersionID *uuid.UUID
	UpdatedAt        time.Time
	Version          *int32
	Subject          *string
	Body             *string
	AiGenerated      *bool
}

func (q *Queries) ListTemplates(ctx context.Context, tenantID uuid.UUID) ([]ListTemplatesRow, error) {
	rows, err := q.db.Query(ctx, listTemplates, tenantID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListTemplatesRow
	for rows.Next() {
		var i ListTemplatesRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.CurrentVersionID,
			&i.UpdatedAt,
			&i.Version,
			&i.Subject,
			&i.Body,
			&i.AiGenerated,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

